function makeSteps(template) {
  return template.nodes.map((node, index) => {
    const spec = friendly[node.id] || [node.label,'file','明确目标，产出本步骤的成果',node.goal.split('\n')[0].slice(0,150)]
    return { id:node.id, label:spec[0], icon:spec[1], summary:spec[2], goal:spec[3], role:roleNames[node.role] || 'AI 助手', model:'', deliverable:node.id === 'review' ? '审查报告与待修改事项' : node.id === 'uat' ? '成果摘要与验收清单' : '工作记录与成果说明', maxRounds:'3', independent:node.id==='review', next:template.nodes[index + 1]?.id || 'end', returnTo:template.nodes[Math.max(index-1,0)]?.id || 'end', aiService:'' }
  })
}
