 const order=t.nodes.map(n=>n.id);const at=t.edges.find(e=>e.to==='$human-decision')?.from
 if(at)order.splice(order.indexOf(at)+1,0,'$human-decision');return order.indexOf(a.id)-order.indexOf(b.id)
